import { 
  MeshStandardNodeMaterial, 
  BoxGeometry, 
  PlaneGeometry, 
  SRGBColorSpace, 
  Group, 
  PointLight,
  RepeatWrapping
} from 'three/webgpu';
import { uv, vec3, mix, color, dot, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  const colors = {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38'
  };

  // --- STAGE BACKDROP WITH SPEC GRADIENT STOPS ---
  const backdropGeo = new PlaneGeometry(24, 18);
  const backdropMat = new MeshStandardNodeMaterial({
    roughness: 0.9,
    metalness: 0.1
  });

  // Vertical gradient from #0b0b10 to #14141a
  const vUv = uv();
  backdropMat.colorNode = mix(
    color(colors.background),
    color(colors.surface),
    vUv.y
  );

  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -3.0;
  group.add(backdrop);

  // --- LOCAL LIGHTING ENVELOPE ---
  const keyLight = new PointLight(colors.paper, 1.4, 15);
  keyLight.position.set(-3, 4, 4);
  group.add(keyLight);

  const rimLight = new PointLight(colors.accent, 1.5, 10);
  rimLight.position.set(4, -4, 3);
  group.add(rimLight);

  // --- TEXT COLUMN CONTAINER ---
  const textContainer = new Group();
  textContainer.position.set(-1.6, 0, 0.2);
  group.add(textContainer);

  const headlineText = ctx.fontAtlas.createText("Inside the atelier", {
    fontSize: 0.38,
    color: colors.paper,
    align: 'left'
  });
  headlineText.position.set(0, 1.9, 0);
  textContainer.add(headlineText);

  const labels = [
    "DIAL ROOM",
    "ESCAPEMENT BENCH",
    "CNC HALL",
    "FINISHING LAB",
    "ARCHIVE VAULT",
    "ASSEMBLY LINE ONE"
  ];

  const labelObjects = [];
  labels.forEach((text) => {
    const labelMesh = ctx.fontAtlas.createText(text, {
      fontSize: 0.14,
      color: colors.accent,
      align: 'left',
      letterSpacingPx: 2
    });
    labelMesh.position.set(0, -0.2, 0);
    labelMesh.scale.set(0.001, 0.001, 0.001);
    textContainer.add(labelMesh);
    labelObjects.push(labelMesh);
  });

  // --- LOOP GALLERY COLUMN ---
  const columnGroup = new Group();
  columnGroup.position.x = 0.9;
  group.add(columnGroup);

  const plateCount = 6;
  const plateWidth = 1.9;
  const plateHeight = 1.2;
  const pitch = 1.5;
  const totalHeight = plateCount * pitch; // 9.0 units
  const plates = [];

  const plateGeo = new BoxGeometry(plateWidth, plateHeight, 0.04);
  const accentStripGeo = new BoxGeometry(0.03, plateHeight, 0.05);
  const bevelGeo = new BoxGeometry(plateWidth + 0.06, plateHeight + 0.06, 0.02);

  const bevelMat = new MeshStandardNodeMaterial({
    color: colors.ink,
    roughness: 0.5,
    metalness: 0.5
  });

  const baseImageUrl = config.imageUrl || '/prism-mock/home/nodes/feature-card.png';

  // Specific filmic transforms per plate (tints strictly on spec palette to avoid blue drift)
  const filmicConfigs = [
    { tint: '#e8ecf2', scale: 1.0, uShift: 0.0, vShift: 0.0, contrast: 1.1 },
    { tint: '#ff949b', scale: 1.15, uShift: 0.2, vShift: 0.1, contrast: 1.3 },
    { tint: '#a2a7af', scale: 0.95, uShift: 0.4, vShift: 0.3, contrast: 1.0 },
    { tint: '#ffd6d8', scale: 1.1, uShift: 0.1, vShift: 0.4, contrast: 1.2 },
    { tint: '#d8dadc', scale: 1.25, uShift: 0.3, vShift: 0.15, contrast: 1.15 },
    { tint: '#ff4d5a', scale: 1.05, uShift: 0.25, vShift: 0.2, contrast: 1.4 }
  ];

  const plateMaterials = [];

  ctx.textureLoader.loadTexture(baseImageUrl).then((tex) => {
    tex.colorSpace = SRGBColorSpace;
    tex.wrapS = RepeatWrapping;
    tex.wrapT = RepeatWrapping;

    filmicConfigs.forEach((cfg, idx) => {
      const mat = plateMaterials[idx];
      if (mat) {
        // TSL Graph: Map texture, enforce grayscale conversion to kill background blue drift, colorize with spec tint
        const texUv = uv().mul(cfg.scale).add(vec3(cfg.uShift, cfg.vShift, 0));
        const rgbVal = texture(tex, texUv);
        const luma = dot(rgbVal.rgb, vec3(0.299, 0.587, 0.114));
        const colorized = mix(color(colors.background), color(cfg.tint), luma.mul(cfg.contrast));

        mat.colorNode = colorized;
        mat.needsUpdate = true;
      }
    });
  });

  for (let i = 0; i < plateCount; i++) {
    const plateContainer = new Group();
    plateContainer.position.y = i * pitch - (totalHeight / 2);

    // Ink Bevel Frame
    const bevelMesh = new THREE.Mesh(bevelGeo, bevelMat);
    bevelMesh.position.z = -0.015;
    plateContainer.add(bevelMesh);

    // Custom textured plate
    const plateMat = new MeshStandardNodeMaterial({
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1
    });
    plateMat.colorNode = color(filmicConfigs[i].tint);
    plateMaterials.push(plateMat);

    const plateMesh = new THREE.Mesh(plateGeo, plateMat);
    plateContainer.add(plateMesh);

    // Left Edge Accent Strip Indicator
    const accentMat = new MeshStandardNodeMaterial({
      color: colors.accent,
      emissive: colors.accent,
      emissiveIntensity: 1.4,
      roughness: 0.1
    });
    const accentStrip = new THREE.Mesh(accentStripGeo, accentMat);
    accentStrip.position.set(-plateWidth / 2 - 0.015, 0, 0.01);
    accentStrip.scale.set(1, 0.001, 1);
    plateContainer.add(accentStrip);

    columnGroup.add(plateContainer);
    plates.push({
      container: plateContainer,
      accent: accentStrip,
      originalY: i * pitch,
      index: i
    });
  }

  // --- SCROLL DRIVEN SEAMLESS LOOP LOGIC ---
  let scrollTargetY = 0;
  let scrollCurrentY = 0;
  const damping = 0.12;

  const onScroll = (event) => {
    const delta = event.deltaY || 0;
    scrollTargetY -= (delta * 0.003) * pitch;
  };

  const updateLoop = () => {
    // Standard damping interpolation
    scrollCurrentY += (scrollTargetY - scrollCurrentY) * damping;
    columnGroup.position.y = scrollCurrentY;

    let closestPlate = null;
    let minDistance = Infinity;

    plates.forEach((plate) => {
      let worldY = columnGroup.position.y + plate.originalY;
      const halfHeight = totalHeight / 2;
      worldY = ((worldY + halfHeight) % totalHeight);
      if (worldY < 0) worldY += totalHeight;
      worldY -= halfHeight;

      plate.container.position.y = worldY - columnGroup.position.y;

      const dist = Math.abs(worldY);
      if (dist < minDistance) {
        minDistance = dist;
        closestPlate = plate;
      }
    });

    plates.forEach((plate) => {
      const isFocused = plate === closestPlate;

      gsap.to(plate.container.scale, {
        x: isFocused ? 1.06 : 1.0,
        y: isFocused ? 1.06 : 1.0,
        z: isFocused ? 1.06 : 1.0,
        duration: 0.35,
        ease: 'power2.out'
      });

      gsap.to(plate.accent.scale, {
        y: isFocused ? 1.0 : 0.001,
        duration: 0.3,
        ease: 'power2.out'
      });

      const label = labelObjects[plate.index];
      if (label) {
        if (isFocused) {
          gsap.to(label.scale, { x: 1, y: 1, z: 1, duration: 0.35, ease: 'back.out(1.5)' });
          gsap.to(label.position, { y: 0, duration: 0.2 });
        } else {
          gsap.to(label.scale, { x: 0.001, y: 0.001, z: 0.001, duration: 0.2, ease: 'power2.in' });
          gsap.to(label.position, { y: -0.2, duration: 0.2 });
        }
      }
    });
  };

  group.userData.handlers = {
    wheel: onScroll
  };

  gsap.ticker.add(updateLoop);

  // --- PRIMITIVES INTERACTION ---
  let flyThroughCtrl = null;
  if (ctx.primitives && ctx.primitives['fly-through']) {
    flyThroughCtrl = ctx.primitives['fly-through'](group, { depthUnits: 2.5 });
  }

  // --- CLEANUP ---
  group.userData.cleanup = () => {
    gsap.ticker.remove(updateLoop);
    if (flyThroughCtrl && flyThroughCtrl.cleanup) {
      flyThroughCtrl.cleanup();
    }
    backdropGeo.dispose();
    backdropMat.dispose();
    plateGeo.dispose();
    accentStripGeo.dispose();
    bevelGeo.dispose();
    bevelMat.dispose();
    plateMaterials.forEach(m => m.dispose());
    accentMat.dispose();
  };

  return group;
}
